/** 题干语义向量（JSON 数组），不向前端返回 */
@JsonIgnore
private String embedding;

/** 状态：1 正常，0 删除（软删除标记） */
@TableLogic
@JsonIgnore
private Integer status;

LambdaQueryWrapper<Question> wrapper = new LambdaQueryWrapper<>();
wrapper.eq(Question::getUserId, UserContext.getUserId())
        .eq(subjectId != null, Question::getSubjectId, subjectId)
        .eq(knowledgePointId != null, Question::getKnowledgePointId, knowledgePointId)
        .orderByDesc(Question::getCreateTime);
return questionMapper.selectPage(new Page<>(pageNum, pageSize), wrapper);

Question question = new Question();
question.setUserId(UserContext.getUserId());
question.setSubjectId(requireSubject(request.getSubjectId()));
question.setStem(QuestionContent.validatedStem(request.getStem()));
question.setAnswer(request.getAnswer());
question.setSource(request.getSource());
String savedImageUrl = null;
try {
    if (StringUtils.hasText(request.getImageBase64())) {
        savedImageUrl = fileStorageUtil.saveBase64Image(request.getImageBase64());
        question.setImageUrl(savedImageUrl);
    }
    questionMapper.insert(question);
    // 录入成功建立固定第 1/2/4/7/15 天复习计划，不动态估计遗忘曲线。
    reviewPlanService.createPlans(question);
    return question.getId();

String stem = QuestionContent.validatedStem(request.getStem());
boolean aiInputChanged = !Objects.equals(question.getSubjectId(), request.getSubjectId())
        || !Objects.equals(question.getStem(), stem)
        || !Objects.equals(question.getAnswer(), request.getAnswer());

QuestionRecognitionClient.Extraction extraction = client.recognize(
        request.getImageBase64(),
        subjects.stream().map(Subject::getName).filter(StringUtils::hasText).toList());

Subject matchedSubject = StringUtils.hasText(extraction.subjectName())
        ? subjectsByName.get(normalizeSubjectName(extraction.subjectName()))
        : null;
return new QuestionRecognitionResult(
        matchedSubject == null ? null : matchedSubject.getId(),
        matchedSubject == null ? null : matchedSubject.getName(),
        extraction.stem(),
        emptyToNull(extraction.studentAnswer()),
        emptyToNull(extraction.source()));

body.put("response_format", Map.of("type", "json_object"));
body.put("temperature", 0.2);
body.put("max_tokens", CHAT_MAX_TOKENS);
body.put("stream", false);

JsonNode response = post("/chat/completions", body);
requireResponseModel(response, chatModel, "Chat");
JsonNode content = response.path("choices").path(0).path("message").path("content");
if (!content.isTextual() || !StringUtils.hasText(content.asText())) {
    throw new IllegalStateException("大模型响应缺少 choices[0].message.content");
}
return content.asText();

if (json.size() != 4
        || !json.has("knowledgePointId")
        || !json.has("errorCause")
        || !json.has("analysis")
        || !json.has("difficulty")) {
    throw new IllegalArgumentException("AI 解析响应字段必须与约定结构完全一致");

Set<Long> candidateIds = candidates.stream().map(KnowledgePoint::getId).collect(Collectors.toSet());
if (knowledgePoint == null || !knowledgePoint.isIntegralNumber()
        || !knowledgePoint.canConvertToLong()
        || !candidateIds.contains(knowledgePoint.asLong())) {
    throw new IllegalArgumentException("AI 解析知识点必须属于当前候选集合");
}
if (difficulty == null || !difficulty.isIntegralNumber()
        || !difficulty.canConvertToInt()
        || difficulty.asInt() < 1 || difficulty.asInt() > 5) {
    throw new IllegalArgumentException("AI 解析难度必须是 1-5 的整数");

boolean completed = Boolean.TRUE.equals(transactionTemplate.execute(status -> {
    int questionRows = questionMapper.update(null, matchingInput(question)
            .set(Question::getEmbedding, embedding)
            .set(Question::getKnowledgePointId, knowledgePointId)
            .set(Question::getDifficulty, difficulty));
    if (questionRows != 1) {
        status.setRollbackOnly();
        return false;

Long ownerId = question.getUserId();
List<Question> pool = questionMapper.selectList(new LambdaQueryWrapper<Question>()
        .eq(Question::getUserId, ownerId)
        .eq(Question::getSubjectId, question.getSubjectId())
        .ne(Question::getId, question.getId())
        .isNotNull(Question::getEmbedding));

if (result.size() < TOP_N) {
    ragService.retrieveSimilar(question, TOP_N).stream()
            .filter(q -> ownerId.equals(q.getUserId()))
            .filter(q -> !questionId.equals(q.getId()))
            .forEach(q -> result.putIfAbsent(q.getId(), q));
}
return new ArrayList<>(result.values()).stream().limit(TOP_N).toList();

Question question = access.ownQuestion(questionId);
String hash = inputHash(question);
LearningContent cached = find(questionId);
if (cached != null && hash.equals(cached.getInputHash())) return view(cached, true);
// Cache hits remain available even when no model credential is configured.
llmClient.verifyReady();

return transactionTemplate.execute(status -> {
    Question current = questionMapper.selectByIdForUpdate(questionId);
    if (current == null || !hash.equals(inputHash(current))) {
        throw new IllegalStateException("题目内容已变化，请重新学习");
    }
    LearningContent row = find(questionId);
    // Recheck inside the short write transaction for concurrent requests on other instances.
    if (row != null && hash.equals(row.getInputHash())) return view(row, true);

if (!access.originalPracticed(questionId)) {
    return new PracticeResourceVO(q.getId(), null, q.getStem(), q.getAnswer(), q.getDifficulty(), "original");
}
List<VariantQuestion> variants = variantService.list(questionId);
VariantQuestion available = variants.stream().filter(v -> !Boolean.TRUE.equals(v.getPracticed())).findFirst().orElse(null);
String source = "existing";
if (available == null) {
    List<VariantQuestion> supplied = variantService.generate(questionId);
    if (supplied.isEmpty()) throw new BizException("暂无可用练习题，可重做已练题或稍后重试");
    available = supplied.getFirst();
    source = "generated";

Set<String> stems = new HashSet<>();
current.forEach(v -> stems.add(normalizedStem(v.getStem())));
for (VariantQuestion variant : variants) {
    if (!stems.add(normalizedStem(variant.getStem()))) {
        throw new IllegalArgumentException("模型返回重复题目，未保存");
    }
    if (variantQuestionMapper.insert(variant) != 1) {
        throw new IllegalStateException("变式题保存失败");

if ((request.getQuestionId() == null) == (request.getVariantId() == null)) {
    throw new BizException("错题与变式题必须且只能选择一项");
}
Question question = resolveQuestion(request);

int delta = request.getIsCorrect() == 1 ? MASTERY_UP : -MASTERY_DOWN;
int updated = questionMapper.update(null, new LambdaUpdateWrapper<Question>()
        .eq(Question::getId, question.getId())
        .eq(Question::getUserId, UserContext.getUserId())
        .setSql("mastery = LEAST(100, GREATEST(0, mastery + {0}))", delta));
if (updated != 1) {
    throw new BizException(ResultCode.SERVER_ERROR.getCode(), "掌握度更新失败，请重试");

LocalDate base = LocalDate.now();
for (int i = 0; i < REVIEW_DAYS.length; i++) {
    ReviewPlan plan = new ReviewPlan();
    plan.setUserId(question.getUserId());
    plan.setQuestionId(question.getId());
    plan.setReviewStage(i + 1);
    plan.setPlanDate(base.plusDays(REVIEW_DAYS[i]));
    reviewPlanMapper.insert(plan);

public Question ownQuestion(Long id) {
    Question q = questionMapper.selectById(id);
    if (q == null) throw new BizException(ResultCode.NOT_FOUND.getCode(), "错题不存在");
    if (!"student".equals(UserContext.getRole()) || !q.getUserId().equals(UserContext.getUserId())) {
        throw new BizException(ResultCode.FORBIDDEN.getCode(), "无权访问该学习资源");
    }
    return q;

