private boolean isTransient(RestClientException exception) {
    if (exception instanceof ResourceAccessException) {
        return isConnectionFailure(exception);
    }
    if (exception instanceof HttpClientErrorException.TooManyRequests rateLimit) {
        return PLATFORM_OVERLOAD_CODE.matcher(rateLimit.getResponseBodyAsString()).find();
    }
    return exception instanceof HttpServerErrorException;
}

private LambdaUpdateWrapper<Question> matchingInput(Question question) {
    LambdaUpdateWrapper<Question> wrapper = new LambdaUpdateWrapper<Question>()
            .eq(Question::getId, question.getId())
            .eq(Question::getSubjectId, question.getSubjectId())
            .eq(Question::getStem, question.getStem());
    if (question.getAnswer() == null) {
        wrapper.isNull(Question::getAnswer);
    } else {
        wrapper.eq(Question::getAnswer, question.getAnswer());
    }
    return wrapper;
}

public static String plainText(String input) {
    if (input == null) {
        return "";
    }
    if (!MARKUP.matcher(input).find()) {
        return input.replace("\r\n", "\n").replace('\r', '\n').trim();
    }
    Element body = Jsoup.parseBodyFragment(sanitize(input)).body();
    for (Element index : body.select("sup, sub")) {
        index.replaceWith(new TextNode((index.tagName().equals("sup") ? "^(" : "_(") + index.text() + ")"));
    }
    body.select("br").forEach(element -> element.replaceWith(new TextNode("\n")));
    body.select("p, li, ul, ol").forEach(element -> element.appendChild(new TextNode("\n")));
    return body.wholeText().replace('\u00a0', ' ').replaceAll("\\n{3,}", "\n\n").trim();
}

private Path resolveUploadPath(String imageUrl) {
    if (!isUploadPath(imageUrl)) {
        throw new BizException("题目图片路径无效");
    }
    Path root = Paths.get(uploadDir).toAbsolutePath().normalize();
    String relative = imageUrl.substring("/uploads/".length());
    Path resolved = root.resolve(relative).normalize();
    if (!resolved.startsWith(root)) {
        throw new BizException("题目图片路径无效");
    }
    return resolved;
}

